import sys

def find_b_array(n, a):
    mex = [0] * (n + 1)
    used = [False] * (n + 1)
    b = []

    for i in range(n):
        if a[i] != mex[i]:
            return -1
        while used[mex[i]]:
            mex[i] += 1
        b.append(mex[i])
        used[mex[i]] = True
        mex[i + 1] = mex[i]

    return b

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    a = list(map(int, input[1:]))
    result = find_b_array(n, a)
    if result == -1:
        print(-1)
    else:
        print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
